import DodoPayments from 'dodopayments'

/**
 * Dodo Payments Node.js SDK client.
 *
 * Server-side only. Never expose DODO_API_KEY to the client.
 *
 * Lazy singleton — constructed on first use so module evaluation
 * never throws at build time when the env var is absent.
 */
let _dodo: DodoPayments | null = null

export function getDodoClient(): DodoPayments {
  if (!_dodo) {
    const token = process.env.DODO_API_KEY ?? process.env.DODO_PAYMENTS_API_KEY ?? ''
    _dodo = new DodoPayments({ bearerToken: token })
  }
  return _dodo
}

/** Convenience proxy — use `dodo.x` in existing code unchanged. */
export const dodo: DodoPayments = new Proxy({} as DodoPayments, {
  get(_target, prop) {
    return (getDodoClient() as unknown as Record<string | symbol, unknown>)[prop]
  },
})

